      "type": "Number",
      "displayName": "Total Amount",
      "description": "The total amount of the payment, inclusive of discounts and tax",
      "required": true,
      "validation": {
        "warnings": [
          {
            "field": "TotalAmount",
            "details": "Must match the sum of the line amounts."
          }
        ],
        "information": []
      }
    },
    "currency": {
      "type": "String",
      "displayName": "Currency",
      "description": "Currency of the payment",
      "required": true
    },
