          "displayName": "Links",
          "description": "A collection of linked transactions",
          "properties": {
            "id": {
              "type": "String",
              "displayName": "Identifier",
              "description": "The identifier for the referenced transaction",
              "required": true
            },
            "amount": {
              "type": "Number",
              "displayName": "Amount",
              "description": "The amount by which the balance of the linked entity is altered, in the currency of the linked entity",
              "required": true
            },
            "type": {
              "type": "String",
              "displayName": "Link Type",
              "description": "The type of transaction that is being linked",
              "options": [
                {
                  "value": "Invoice",
                  "type": "String",
                  "displayName": "Invoice",
                  "required": false
                },
                {
                  "value": "CreditNote",
                  "type": "String",
                  "displayName": "CreditNote",
                  "required": false
                },
                {
                  "value": "Other",
                  "type": "String",
                  "displayName": "Other",
                  "required": false
                }
              ],
              "required": true
            }
          },
          "required": true
        }
      },
      "required": true,
      "validation": {
        "warnings": [
          {
            "field": "Lines",
            "details": "Only one line may be specified"
          }
        ],
        "information": []
      }
    }
  },
  "required": true
}

